import Testing
@testable import Screens

struct BookEditTests {
    @Test("book-edit is refused to someone signed in without books.write")
    func refused() {
        #expect(Access.decide(permission: bookEditSchema.permission, session: Session(signedIn: true, permissions: [])) == .refused)
    }

    @Test("book-edit sends someone signed out to sign in")
    func signIn() {
        #expect(Access.decide(permission: bookEditSchema.permission, session: Session(signedIn: false, permissions: [])) == .signIn)
    }

    @Test("book-edit opens to someone who holds books.write")
    func allowed() {
        #expect(Access.decide(permission: bookEditSchema.permission, session: Session(signedIn: true, permissions: ["books.write"])) == .allowed)
    }
}
